import { clamp } from "../core/number";
import { logo } from "../settings/app-resources";
import { useSkinImage, type SkinImageReader } from "./skin-image";
import {
  canvasDecorationStyle,
  canvasPanelStyle,
  type SkinCanvasDecoration,
  type SkinCanvasGeometry,
} from "./skin-canvas-preview";
import type { CSSProperties } from "react";

// Fixed display samples from MSIME-Windows 04a8df56 settings candidate partials.
// These are not user input or candidates generated by the shared runtime.
export const previewSamples = [
  ["你们", "rR"],
  ["你", "rX"],
  ["尼", "uV"],
  ["妮", "nV"],
  ["泥", "dV"],
  ["逆", "zQ"],
  ["拟", "fR"],
  ["腻", "oD"],
  ["拧", "nG"],
] as const;

/** A package background as the preview draws it: an image URL from the bounded host reader, never one from the manifest. */
export type PreviewBackground = {
  url: string;
  fit: "cover" | "contain" | "stretch";
  opacity: number;
};

/** 预览要预留的最高排布：设置页上能切换的排列方式和每页数量里最高的那一种。 */
export type PreviewReserve = { orientation: "horizontal" | "vertical"; count: number };

type SkinCandidatePreviewProps = Parameters<typeof SkinCandidatePreview>[0];

/**
 * 设置页顶部的候选预览：高度按 `reserve` 预留，切换横向／纵向或拖动每页数量时预览框不变高、不变矮，下面的控件就不会在鼠标底下跳动。
 *
 * 预留靠一份不可见的同款样例撑开：它和实际样例叠在同一个网格单元里，用同样的字号、皮肤几何和装饰带，量出来的就是那种排布真实的高度，不必按行高去估算，也就不会裁掉大皮肤或装饰图。实际样例在格子里垂直居中。不传 `reserve` 时与 `SkinCandidatePreview` 完全相同。
 */
export function ReservedCandidatePreview({
  reserve,
  ...props
}: SkinCandidatePreviewProps & { reserve?: PreviewReserve }) {
  if (!reserve) return <SkinCandidatePreview {...props} />;
  return (
    <div className="grid min-w-0 flex-1 grid-cols-[minmax(0,1fr)] items-center justify-items-start [&>*]:[grid-area:1/1]">
      <SkinCandidatePreview {...props} />
      {/* 只为占位：不画图片（装饰图和背景图都是绝对定位，不影响尺寸），始终带拼音行，免得隐藏拼音行时预览变矮。 */}
      <div className="invisible" aria-hidden="true" data-preview-reserve="">
        <SkinCandidatePreview
          orientation={reserve.orientation}
          count={reserve.count}
          preedit
          helpcode={props.helpcode}
          decorated={props.decorated}
          ghost
        />
      </div>
    </div>
  );
}

export function SkinCandidatePreview({
  orientation,
  decorated = false,
  image,
  onImageError,
  background,
  onBackgroundError,
  count = 6,
  preedit = true,
  helpcode = false,
  ghost = false,
  brand = true,
  canvas = null,
  panelUrl,
  readImage,
  skinId = "",
  revision = 0,
}: {
  orientation: "horizontal" | "vertical";
  decorated?: boolean;
  image?: string;
  onImageError?: () => void;
  background?: PreviewBackground;
  onBackgroundError?: () => void;
  count?: number;
  preedit?: boolean;
  /** Off unless the caller says otherwise: the core's default scheme is 全拼, whose helper codes stay out of the candidate window by default. */
  helpcode?: boolean;
  /** 只用来占位的那一份不带 `data-preview-layout`，读预览排布的地方只会找到实际样例。 */
  ghost?: boolean;
  /** 画不画首行的水杉 logo。macOS 和 Windows 按 `show_app_logo` 隐藏它，拼音行也隐藏时首行整行不画，和候选窗一致。 */
  brand?: boolean;
  /** 一个 canvas 包的九宫格、内外留白、行距与自由挂件；只对它画面板，其余包与以前逐位相同。 */
  canvas?: SkinCanvasGeometry | null;
  /** 已经浏览器解码成功的面板地址；读取成功但尚未解码时不传。 */
  panelUrl?: string;
  /** canvas 面板与挂件的包内图片读取器。 */
  readImage?: SkinImageReader;
  /** 图片读取用的包 id。 */
  skinId?: string;
  /** 宿主重扫皮肤目录的代数，图片随之重读。 */
  revision?: number;
}) {
  const horizontal = orientation === "horizontal";
  const visibleCount = Number.isFinite(count) ? clamp(Math.trunc(count), 1, 9) : 6;
  const panel = canvas?.panel ?? null;
  const framed = decorated || canvas !== null;
  const content = (
    <div
      className={`container${preedit ? "" : " preedit-hidden"}`}
      data-panel={panelUrl ? "" : undefined}
    >
      {panel && panelUrl && (
        <div
          className="skin-panel"
          aria-hidden="true"
          style={canvasPanelStyle(panel, panelUrl) as CSSProperties}
        />
      )}
      {/* canvas 面板替代卡片底色，包的背景图不再叠一层，与 Windows 和网页引擎相同。 */}
      {background && !panelUrl && (
        <img
          className="skin-background-image"
          src={background.url}
          alt=""
          style={{
            objectFit: background.fit === "stretch" ? "fill" : background.fit,
            opacity: background.opacity,
          }}
          onError={onBackgroundError}
        />
      )}
      {/* 水杉 logo 打头放在首行；隐藏拼音时首行仍在，只放 logo，logo 也不画时首行整行不画。它在拼音行之前，上游的 `.pinyin + .row-wrapper` 选择器才能照常匹配。 */}
      {!preedit && brand && (
        <div className="row candidate-brand-row">
          <img className="candidate-brand" src={logo} alt="" />
        </div>
      )}
      <div className="row pinyin" hidden={!preedit}>
        {preedit && brand && <img className="candidate-brand" src={logo} alt="" />}
        <div className="text">
          ni'mf
          <span className="cursor" />
        </div>
        <div className="hidden-pinyin">n</div>
      </div>
      {previewSamples.slice(0, visibleCount).map(([text, code], index) => (
        <div
          key={index}
          className={`row-wrapper${horizontal && index === 0 ? " first-row-wrapper" : ""}`}
        >
          <div className={`row cand${index === 0 ? " first" : ""}`}>
            <div className="text">
              <span className={horizontal ? "num" : "cand-no"}>{index + 1}</span>
              {horizontal ? (
                <>
                  {text}
                  {helpcode && <span className="cand-helpcode">({code})</span>}
                </>
              ) : (
                <span className="cand-content">
                  {text}
                  {helpcode && <span className="cand-helpcode">({code})</span>}
                </span>
              )}
            </div>
          </div>
        </div>
      ))}
    </div>
  );
  return (
    <div
      className={`candidate wnd-${horizontal ? "h" : "v"}`}
      data-preview-layout={ghost ? undefined : orientation}
      data-canvas={canvas ? "" : undefined}
      data-canvas-line-gap={canvas && canvas.lineGap !== null ? "" : undefined}
    >
      {framed ? (
        <div className="containerParent">
          {image && (
            <img className="skin-decoration-image" src={image} alt="" onError={onImageError} />
          )}
          {canvas && canvas.below.length > 0 && (
            <SkinCanvasLayer
              layer="below"
              decorations={canvas.below}
              readImage={readImage}
              skinId={skinId}
              revision={revision}
            />
          )}
          {content}
          {canvas && canvas.above.length > 0 && (
            <SkinCanvasLayer
              layer="above"
              decorations={canvas.above}
              readImage={readImage}
              skinId={skinId}
              revision={revision}
            />
          )}
        </div>
      ) : (
        content
      )}
    </div>
  );
}

/** 面板之下或之上的一层自由挂件；每个挂件各自经有界读取器解码，解不出来就不画。 */
function SkinCanvasLayer({
  layer,
  decorations,
  readImage,
  skinId,
  revision,
}: {
  layer: "below" | "above";
  decorations: SkinCanvasDecoration[];
  readImage?: SkinImageReader;
  skinId: string;
  revision: number;
}) {
  return (
    <div className={`skin-layer skin-layer-${layer}`} aria-hidden="true">
      {decorations.map((decoration, index) => (
        <SkinCanvasDecorationImage
          key={`${index}:${decoration.image}`}
          decoration={decoration}
          readImage={readImage}
          skinId={skinId}
          revision={revision}
        />
      ))}
    </div>
  );
}

function SkinCanvasDecorationImage({
  decoration,
  readImage,
  skinId,
  revision,
}: {
  decoration: SkinCanvasDecoration;
  readImage?: SkinImageReader;
  skinId: string;
  revision: number;
}) {
  const image = useSkinImage(readImage, skinId, decoration.image, revision);
  if (!image?.url) return null;
  return (
    <div className="skin-picture" style={canvasDecorationStyle(decoration) as CSSProperties}>
      <img src={image.url} alt="" />
    </div>
  );
}
